import csv, re, datetime, collections
rows=list(csv.DictReader(open('expenses.csv')))
# independent parse
def pd(s):
    s=s.strip()
    for f in ('%Y-%m-%d','%m/%d/%Y','%d %b %Y'):
        try: return datetime.datetime.strptime(s,f).date()
        except: pass
    raise ValueError(s)
def ct(s):
    s=re.sub(r'[^0-9.]','',s)
    return round(float(s)*100)
alias={"taxi":"Travel","uber":"Travel","flight":"Travel","hotel":"Lodging","airbnb":"Lodging","lunch":"Meals","dinner":"Meals","coffee":"Meals","saas":"Software","software":"Software","license":"Software","books":"Learning","course":"Learning"}
# dedupe by id keeping first, same as script
seen=set(); ded=[]
for r in rows:
    if r['id'] in seen: continue
    seen.add(r['id']); ded.append(r)
print("dupes dropped:", len(rows)-len(ded))
oct_rows=[r for r in ded if pd(r['date']).year==2026 and pd(r['date']).month==10 and r['status'].strip().lower()!='void']
print("oct non-void items:", len(oct_rows))
cats=collections.defaultdict(lambda:[0,0]); tot=0
for r in oct_rows:
    c=ct(r['amount']); cat=alias[r['category'].strip().lower()]
    cats[cat][0]+=1; cats[cat][1]+=c; tot+=c
for k,v in sorted(cats.items(), key=lambda kv:(-kv[1][1],kv[0])): print(k,v[0],f"${v[1]//100:,}.{v[1]%100:02d}")
print("total", f"${tot//100:,}.{tot%100:02d}")
print("count all", sum(v[0] for v in cats.values()))
print("flags", [(r['id'],ct(r['amount'])) for r in oct_rows if ct(r['amount'])>50000])
# check id conflicts across duplicates
d=collections.defaultdict(list)
for r in rows: d[r['id']].append((r['date'],r['status'],r['amount'],r['category']))
for k,v in d.items():
    if len(v)>1 and len(set(v))>1: print("CONFLICT", k, v)
EOF
